// ============================================================================
//  Скетч чтения/записи RW1990 (iButton) с записью ключа из терминала ПК
//  Оптимизированная версия: F() для строк, антидребезг кнопки, единая
//  процедура записи, расширенный парсер HEX, неблокирующие мигания.
// ============================================================================
#include <OneWire.h>
#include <avr/pgmspace.h>
#include <string.h>

#define pin 3
OneWire ibutton(pin);
const int buttonPin = 4;
const int ledPin    = 5;

// Режимы
enum : byte {
  REG_READ       = 0,   // чтение (редко моргает)
  REG_WRITE_UNI  = 1,   // запись универсального (горит, 2 раза гаснет)
  REG_WRITE_COPY = 2,   // запись копии (горит, 1 раз гаснет)
  REG_WRITE_PC   = 3    // запись с ПК через терминал
};

byte Readkey[8];       // считанный ключ
const byte Unikey[8] PROGMEM = { 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x14 };
byte crc;

bool buttonFlag    = false;
bool Tabletka      = false;
bool RepairKey     = false;
byte Regim         = REG_READ;

unsigned long lastUpdate[2];   // 0 - LED, 1 - кнопка

// ---------- Антидребезг кнопки ----------
const unsigned long DEBOUNCE_MS = 20;
bool buttonRawState    = false;
bool buttonStableState = false;
unsigned long buttonRawChangeMs = 0;

// ---------- Тройной клик ----------
const unsigned long TRIPLE_CLICK_WINDOW = 1500;   // мс
byte clickCount = 0;
unsigned long clickWindowStart = 0;
unsigned long pendingPressMs   = 0;
bool pendingShort = false;

// ---------- Режим терминала ----------
char pcLine[64];
byte pcLineLen = 0;
bool terminalBlinkActive = false;
byte terminalBlinkCount  = 0;
unsigned long terminalBlinkLast = 0;
bool terminalBlinkOn   = false;
const unsigned long BLINK_HALF_PERIOD = 250;      // 2 Гц

// ============================================================================
void setup() {
  pinMode(ledPin, OUTPUT);
  pinMode(buttonPin, INPUT_PULLUP);

  unsigned long now = millis();
  lastUpdate[0] = now;
  lastUpdate[1] = now;

  bool raw = !digitalRead(buttonPin);
  buttonRawState    = raw;
  buttonStableState = raw;
  buttonRawChangeMs = now;

  Serial.begin(9600);
  Serial.println(F("====> Чтение"));
}

// ============================================================================
void loop() {
  switch (Regim) {
    case REG_READ:       doReadMode();      break;
    case REG_WRITE_UNI:
    case REG_WRITE_COPY: doCopyWriteMode(); break;
    case REG_WRITE_PC:   TerminalMode();    break;
  }

  processShortClickTimeout();

  // В режиме терминала, пока идёт мигание после записи, LED управляется отдельно
  if (!(Regim == REG_WRITE_PC && terminalBlinkActive)) LED(Regim);

  Knopka();
}

// ============================================================================
//                       Чтение
// ============================================================================
void doReadMode() {
  if (ibutton.search(Readkey)) {
    Tabletka = true;
    digitalWrite(ledPin, HIGH);
    delay(100);
    digitalWrite(ledPin, LOW);

    Serial.print(F("Читаем:    "));
    printHex(Readkey, 8);
    crc = ibutton.crc8(Readkey, 7);
    printCrc(crc, Readkey[7]);
  } else {
    ibutton.reset_search();
    delay(50);
  }
}

// ============================================================================
//                       Запись универсального / копии
// ============================================================================
void doCopyWriteMode() {
  // Поиск устройства, если не включён принудительный режим
  if (!RepairKey) {
    ibutton.reset_search();
    delay(50);
    byte rom[8];
    if (!ibutton.search(rom)) return;
  }
  delay(100);

  // Показ «Было:» — пропускается, если пользователь ещё держит кнопку
  if (!buttonFlag) {
    Serial.println();
    ibutton.skip();
    ibutton.reset();
    ibutton.write(0x33);
    Serial.print(F("Было:      "));
    byte existing[8];
    for (byte i = 0; i < 8; i++) existing[i] = ibutton.read();
    printHex(existing, 8);
    Serial.println();
  }

  // Формируем целевой массив
  byte target[8];
  if (Regim == REG_WRITE_UNI) memcpy_P(target, Unikey, 8);
  else                        memcpy(target, Readkey, 8);

  if (writeAndVerify(target)) {
    Regim     = REG_READ;
    RepairKey = false;
    Serial.println();
    Serial.println(F("====> Чтение"));
    lastUpdate[0] = millis();
  }
}

// ============================================================================
//                       Универсальная запись + проверка
// ============================================================================
bool writeAndVerify(const byte* key8) {
  // ---- Разрешение записи (0xD1 + импульс) ----
  ibutton.skip();
  ibutton.reset();
  ibutton.write(0xD1);

  digitalWrite(pin, LOW); pinMode(pin, OUTPUT);
  delayMicroseconds(60);
  pinMode(pin, INPUT); digitalWrite(pin, HIGH);
  delay(10);

  // ---- Команда записи (0xD5) + побайтная запись ----
  Serial.print(F("Пишем:     "));
  ibutton.skip();
  ibutton.reset();
  ibutton.write(0xD5);
  for (byte i = 0; i < 8; i++) {
    writeByte(key8[i]);
    if (key8[i] < 16) Serial.print('0');
    Serial.print(key8[i], HEX);
    if (i < 7) Serial.print(':');
  }
  Serial.println();

  // ---- Запрет записи (0xD1 + импульс) ----
  ibutton.reset();
  ibutton.write(0xD1);
  digitalWrite(pin, LOW); pinMode(pin, OUTPUT);
  delayMicroseconds(10);
  pinMode(pin, INPUT); digitalWrite(pin, HIGH);
  delay(10);

  // ---- Проверка ----
  delay(50);
  ibutton.reset_search();
  delay(50);

  byte rom[8];
  if (!ibutton.search(rom)) {
    Serial.println(F("Проверка: ключ не найден."));
    return false;
  }

  Serial.print(F("Записано:  "));
  printHex(rom, 8);
  crc = ibutton.crc8(rom, 7);
  printCrc(crc, rom[7]);

  bool ok = true;
  for (byte i = 0; i < 8; i++) if (rom[i] != key8[i]) ok = false;

  if (ok) Serial.println(F("=========== Проверка.....   ok ==========="));
  else    Serial.println(F("=========== Ошибка проверки ==========="));

  return ok;
}

// ============================================================================
//                       Запись с ПК
// ============================================================================
bool writeKeyToIButton(const byte* key8) {
  ibutton.reset_search();
  delay(50);

  byte rom[8];
  if (!ibutton.search(rom)) {
    Serial.println(F("Ключ не найден на шине 1-Wire."));
    return false;
  }

  Serial.print(F("Пишем с ПК: "));
  printHex(key8, 8);
  Serial.println();

  return writeAndVerify(key8);
}

// ============================================================================
//                       Терминал (приём строки)
// ============================================================================
void TerminalMode() {
  if (terminalBlinkActive) {
    handleTerminalBlink();
    return;
  }

  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') {
      if (pcLineLen > 0) {
        pcLine[pcLineLen] = '\0';
        processPcLine(pcLine);
        pcLineLen = 0;
      }
    } else if (pcLineLen < sizeof(pcLine) - 1) {
      pcLine[pcLineLen++] = c;
    } else {
      pcLineLen = 0;
      Serial.println();
      Serial.println(F("Ошибка: слишком длинная строка."));
      Serial.print(F("> "));
    }
  }
}

void processPcLine(char* line) {
  byte parsed[8];
  byte n = parseHexBytes(line, parsed, 8);

  byte key8[8];
  if (n == 7) {
    memcpy(key8, parsed, 7);
    key8[7] = ibutton.crc8(parsed, 7);
  } else if (n == 8) {
    memcpy(key8, parsed, 8);
    byte calc = ibutton.crc8(parsed, 7);
    if (calc != parsed[7]) {
      Serial.println(F("Ошибка: CRC не совпадает с указанным 8-м байтом."));
      Serial.print(F("> "));
      return;
    }
  } else {
    Serial.println(F("Ошибка: нужно 7 или 8 байт в виде XX XX XX XX XX XX XX [XX]"));
    Serial.print(F("> "));
    return;
  }

  if (writeKeyToIButton(key8)) {
    Serial.println(F("Запись завершена. Светодиод мигнет 5 раз."));
    startTerminalBlink();
  } else {
    Serial.println(F("Запись не выполнена. Введите ключ заново."));
    Serial.print(F("> "));
  }
}

// ============================================================================
//                       Мигание 5 раз (2 Гц)
// ============================================================================
void startTerminalBlink() {
  terminalBlinkActive = true;
  terminalBlinkCount  = 0;
  terminalBlinkOn     = true;
  digitalWrite(ledPin, HIGH);
  terminalBlinkLast = millis();
}

void handleTerminalBlink() {
  if (millis() - terminalBlinkLast < BLINK_HALF_PERIOD) return;
  terminalBlinkLast += BLINK_HALF_PERIOD;

  if (terminalBlinkOn) {
    digitalWrite(ledPin, LOW);
    terminalBlinkOn = false;
    terminalBlinkCount++;
    if (terminalBlinkCount >= 5) {
      terminalBlinkActive = false;
      Regim = REG_READ;
      Serial.println();
      Serial.println(F("====> Чтение"));
      lastUpdate[0] = millis();
    }
  } else {
    digitalWrite(ledPin, HIGH);
    terminalBlinkOn = true;
  }
}

// ============================================================================
//                       Светодиод
// ============================================================================
void LED(byte N) {
  switch (N) {
    case REG_READ:
      if      (timer(0, 3000)) lastUpdate[0] = millis();
      else if (timer(0, 2950)) digitalWrite(ledPin, HIGH);
      else                     digitalWrite(ledPin, LOW);
      break;

    case REG_WRITE_UNI:
      if      (timer(0, 2000)) lastUpdate[0] = millis();
      else if (timer(0, 1900)) digitalWrite(ledPin, LOW);
      else if (timer(0, 1850)) digitalWrite(ledPin, HIGH);
      else if (timer(0, 1750)) digitalWrite(ledPin, LOW);
      else                     digitalWrite(ledPin, HIGH);
      break;

    case REG_WRITE_COPY:
      if      (timer(0, 2000)) lastUpdate[0] = millis();
      else if (timer(0, 100))  digitalWrite(ledPin, HIGH);
      else                     digitalWrite(ledPin, LOW);
      break;

    case REG_WRITE_PC:
      if (!terminalBlinkActive) digitalWrite(ledPin, HIGH);
      break;
  }
}

// ============================================================================
//                       Кнопка (с антидребезгом)
// ============================================================================
void Knopka() {
  bool raw = !digitalRead(buttonPin);
  unsigned long now = millis();

  if (raw != buttonRawState) {
    buttonRawState     = raw;
    buttonRawChangeMs  = now;
  }

  // Дребезг: ждём стабильного состояния
  if (now - buttonRawChangeMs < DEBOUNCE_MS) {
    checkRepairTrigger();
    return;
  }

  if (buttonRawState == buttonStableState) {
    checkRepairTrigger();
    return;
  }

  // Стабильное изменение
  buttonStableState = buttonRawState;

  if (buttonStableState) {
    // Нажатие
    buttonFlag = true;
    lastUpdate[1] = now;
  } else {
    // Отпускание
    buttonFlag = false;
    handleButtonRelease(now - lastUpdate[1]);
    lastUpdate[0] = millis();
  }
}

// Проверка долгого удержания >5 с для принудительной записи
void checkRepairTrigger() {
  if (buttonFlag && Regim != REG_READ && Regim != REG_WRITE_PC
      && !RepairKey && timer(1, 5000)) {
    RepairKey = true;
    Serial.println(F("====> Запись нечитаемого ключа"));
    Serial.println();
  }
}

void handleButtonRelease(unsigned long pressMs) {
  // В режиме терминала: короткие нажатия игнорируем, длинное >2,5 с — выход
  if (Regim == REG_WRITE_PC) {
    if (pressMs >= 2500) {
      terminalBlinkActive = false;
      digitalWrite(ledPin, LOW);
      Regim = REG_READ;
      Serial.println();
      Serial.println(F("====> Чтение"));
    }
    return;
  }

  if (pressMs >= 5000) {
    Regim = REG_READ;
    if (RepairKey) {
      RepairKey = false;
      Serial.println();
      Serial.println(F("====> Чтение"));
    }
    resetClickSequence();
    return;
  }

  if (pressMs >= 2500) {
    if (Regim != REG_READ) {
      Regim = REG_READ;
      Serial.println(F("====> Чтение"));
    }
    resetClickSequence();
    return;
  }

  if (pressMs >= 1000) {
    if (Regim != REG_WRITE_UNI) {
      Regim = REG_WRITE_UNI;
      Serial.println(F("====> Запись универс.ключа"));
    }
    resetClickSequence();
    return;
  }

  if (pressMs >= 500) {
    if (Tabletka && Regim != REG_WRITE_COPY) {
      Regim = REG_WRITE_COPY;
      Serial.println(F("====> Запись копии"));
    }
    resetClickSequence();
    return;
  }

  // Короткое нажатие <500 мс — кандидат для тройного клика
  registerShortClick(pressMs);
}

// ============================================================================
//                       Тройной клик / одиночное короткое нажатие
// ============================================================================
void registerShortClick(unsigned long pressMs) {
  unsigned long now = millis();

  if (clickCount == 0 || (now - clickWindowStart) > TRIPLE_CLICK_WINDOW) {
    clickCount       = 1;
    clickWindowStart = now;
    pendingPressMs   = pressMs;
    pendingShort     = true;
  } else {
    clickCount++;
    pendingPressMs = pressMs;
    if (clickCount >= 3) {
      clickCount   = 0;
      pendingShort = false;
      enterTerminalMode();
    } else {
      pendingShort = true;
    }
  }
}

void processShortClickTimeout() {
  if (clickCount == 0) return;
  if ((millis() - clickWindowStart) <= TRIPLE_CLICK_WINDOW) return;

  // Одиночное короткое нажатие — прежнее поведение: запись копии
  if (clickCount == 1 && pendingShort) {
    if (Tabletka && Regim != REG_WRITE_COPY) {
      Regim = REG_WRITE_COPY;
      Serial.println(F("====> Запись копии"));
    }
    lastUpdate[0] = millis();
  }
  clickCount   = 0;
  pendingShort = false;
}

void resetClickSequence() {
  clickCount   = 0;
  pendingShort = false;
}

void enterTerminalMode() {
  Regim = REG_WRITE_PC;
  RepairKey = false;
  pcLineLen = 0;
  terminalBlinkActive = false;
  digitalWrite(ledPin, HIGH);

  Serial.println();
  Serial.println(F("Готов записать ключ с ПК. Введите новый ключ в виде XX XX XX XX XX XX XX"));
  Serial.print(F("> "));
  lastUpdate[0] = millis();
}

// ============================================================================
//                       Утилиты
// ============================================================================
// Overflow-safe: корректно работает и при переполнении millis()
bool timer(byte N, unsigned long Period) {
  return (millis() - lastUpdate[N]) >= Period;
}

void printHex(const byte* data, byte len) {
  for (byte i = 0; i < len; i++) {
    if (data[i] < 16) Serial.print('0');
    Serial.print(data[i], HEX);
    if (i < len - 1) Serial.print(':');
  }
}

void printCrc(byte calc, byte stored) {
  Serial.print(F("  CRC:"));
  if (calc == stored) {
    Serial.println(F("ok"));
  } else {
    if (calc < 16) Serial.print('0');
    Serial.println(calc, HEX);
  }
}

bool isHexChar(char c) {
  return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f');
}

byte hexVal(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return c - 'a' + 10;
}

// Принимает строку с разделителями любого вида (пробел, ':', '-', ',').
// Возвращает число байт или 0 при ошибке.
byte parseHexBytes(const char* s, byte* out, byte max) {
  byte n = 0;
  while (*s) {
    while (*s && !isHexChar(*s)) s++;
    if (!*s) break;
    if (!isHexChar(s[1])) return 0;
    if (n >= max)         return 0;
    out[n++] = (hexVal(s[0]) << 4) | hexVal(s[1]);
    s += 2;
  }
  return n;
}

// Побайтная запись (протокол 1-Wire)
int writeByte(byte data) {
  for (byte b = 0; b < 8; b++) {
    if (data & 1) {
      digitalWrite(pin, LOW); pinMode(pin, OUTPUT);
      delayMicroseconds(60);
      pinMode(pin, INPUT); digitalWrite(pin, HIGH);
      delay(10);
    } else {
      digitalWrite(pin, LOW); pinMode(pin, OUTPUT);
      pinMode(pin, INPUT); digitalWrite(pin, HIGH);
      delay(10);
    }
    data >>= 1;
  }
  return 0;
}
